// HasTest applies the HasEdge predicate on the "test" edge.
func HasTest() predicate.BundleAbTestAnalysisSnapshots {
	return predicate.BundleAbTestAnalysisSnapshots(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TestTable, TestColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTestWith applies the HasEdge predicate on the "test" edge with a given conditions (other predicates).
func HasTestWith(preds ...predicate.BundleAbTests) predicate.BundleAbTestAnalysisSnapshots {
	return predicate.BundleAbTestAnalysisSnapshots(func(s *sql.Selector) {
		step := newTestStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleAbTestAnalysisSnapshots) predicate.BundleAbTestAnalysisSnapshots {
	return predicate.BundleAbTestAnalysisSnapshots(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleAbTestAnalysisSnapshots) predicate.BundleAbTestAnalysisSnapshots {
	return predicate.BundleAbTestAnalysisSnapshots(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleAbTestAnalysisSnapshots) predicate.BundleAbTestAnalysisSnapshots {
	return predicate.BundleAbTestAnalysisSnapshots(sql.NotPredicates(p))
}
